ॐ श्री श्याम देवाय नमः ॥ श्री हनुमंते नमः ॥","बाबा श्री श्याम के जन्मोत्सव के पावन अवसर पर उन्हें":"बाबा श्री श्याम के जन्मोत्सव के पावन अवसर पर उन्हें","1,00,001 मोर पंखों":"1,00,001 मोर पंखों","से सजाया जाएगा।":"से सजाया जाएगा।","बाबा के चरणों में अर्पित मोर पंख को अपने घर सहेजें":"बाबा के चरणों में अर्पित मोर पंख को अपने घर सहेजें","घर पर मंगवाएँ और बाबा की इस पावन स्मृति को हमेशा अपने पास रखें।":"घर पर मंगवाएँ और बाबा की इस पावन स्मृति को हमेशा अपने पास रखें।","नाम का व्यक्किगत":"नाम का व्यक्किगत","वीडियो चढ़ावा":"वीडियो चढ़ावा","अर्पित करते हुए पाएं":"अर्पित करते हुए पाएं"}};\nconst stateLang={"andhra pradesh":"te","arunachal pradesh":"hi","assam":"as","bihar":"hi","chhattisgarh":"hi","goa":"hi","gujarat":"gu","haryana":"hi","himachal pradesh":"hi","jharkhand":"hi","karnataka":"kn","kerala":"ml","madhya pradesh":"hi","maharashtra":"mr","manipur":"hi","meghalaya":"hi","mizoram":"hi","nagaland":"hi","odisha":"or","orissa":"or","punjab":"pa","rajasthan":"hi","sikkim":"hi","tamil nadu":"ta","telangana":"te","tripura":"hi","uttar pradesh":"hi","uttarakhand":"hi","west bengal":"bn","delhi":"hi","nct of delhi":"hi","jammu and kashmir":"hi","ladakh":"hi"};\nconst supported=Object.keys(MAP);\nconst select=document.getElementById('ms-language');\nconst svg=document.querySelector('.poster svg');\nconst nodes=[];\nconst norm=v=>String(v??'').replace(/\\s+/g,' ').trim();\nconst browserLang=()=>{for(const x of [...(navigator.languages||[]),navigator.language||'']){const c=String(x).toLowerCase().split('-')[0];if(supported.includes(c))return c;}return 'hi';};\n\n// Capture the SVG's original structure once. We translate the actual SVG text/tspan\n// nodes, not the surrounding HTML. Images, paths, gradients and artwork are untouched.\nif(svg){\n  svg.querySelectorAll('text').forEach(textEl=>{\n    const children=[...textEl.children].filter(x=>x.tagName.toLowerCase()==='tspan');\n    if(children.length){\n      nodes.push({el:textEl,parts:children.map(x=>({el:x,key:norm(x.textContent)})),whole:norm(textEl.textContent)});\n    }else{\n      nodes.push({el:textEl,parts:null,key:norm(textEl.textContent)});\n    }\n  });\n}\n\nfunction applyLanguage(lang){\n  if(!MAP[lang]) lang='hi';\n  document.documentElement.lang=lang;\n  if(select) select.value=lang;\n  const dict=MAP[lang];\n  nodes.forEach(item=>{\n    if(item.parts){\n      item.parts.forEach(part=>{part.el.textContent=dict[part.key] ?? part.key;});\n    }else{\n      item.el.textContent=dict[item.key] ?? item.key;\n    }\n    // Remove old sizing overrides. The SVG viewBox scales the translated text\n    // with the poster, and this avoids forcing English/Hindi widths onto other scripts.\n    item.el.removeAttribute('textLength');\n    item.el.removeAttribute('lengthAdjust');\n  });\n  // Translate document metadata too.\n  const title=document.querySelector('title');\n  if(title) title.textContent=(lang==='hi'?'खाटू श्याम बाबा का जन्मोत्सव — Mandir Setuu':(dict['खाटू श्याम बाबा का']||'Khatu Shyam Baba')+' '+(dict['जन्मोत्सव']||'Janmotsav')+' — Mandir Setuu');\n}\n\nif(select) select.addEventListener('change',e=>applyLanguage(e.target.value));\napplyLanguage(browserLang());\n\nasync function detectIP(){\n  try{const r=await fetch('https://ipapi.co/json/?t='+Date.now(),{cache:'no-store'});if(!r.ok)return null;const d=await r.json();if(d.country_code!=='IN')return null;const state=String(d.region||'').toLowerCase().replace(/\\s+/g,' ').trim();return stateLang[state]||'hi';}catch(e){return null;}\n}\nasync function detectGPS(){\n  if(!navigator.geolocation)return null;\n  try{\n    const pos=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:false,timeout:8000,maximumAge:3600000}));\n    const u='https://api.bigdatacloud.net/data/reverse-geocode-client?latitude='+encodeURIComponent(pos.coords.latitude)+'&longitude='+encodeURIComponent(pos.coords.longitude)+'&localityLanguage=en';\n    const r=await fetch(u,{cache:'no-store'});if(!r.ok)return null;const d=await r.json();\n    if(!String(d.countryName||'').toLowerCase().includes('india'))return null;\n    const state=String(d.principalSubdivision||'').toLowerCase().replace(/\\s+/g,' ').trim();\n    return stateLang[state]||'hi';\n  }catch(e){return null;}\n}\n(async()=>{\n  // Location overrides browser language when it is available.\n  const ip=await detectIP();\n  if(ip) applyLanguage(ip);\n  const gps=await detectGPS();\n  if(gps) applyLanguage(gps);\n})();\n\n// Backend may inject its own Book Now button. We do not create, translate or move it.\n})();\n</script>\n<script id="ms-bookbar-flow">\n(function(){\n  function isBookCandidate(el){\n    if(!el || el.id==='ms-langbar' || el.closest('#ms-langbar')) return false;\n    const cs=getComputedStyle(el);\n    if(cs.position!=='fixed') return false;\n    const r=el.getBoundingClientRect();\n    const bottomDistance=window.innerHeight-r.bottom;\n    const wide=r.width>=Math.min(window.innerWidth*0.55,700);\n    const nearBottom=bottomDistance<=35;\n    return wide && nearBottom && r.height>35 && r.height<220;\n  }\n\n  function fixBookBars(){\n    const all=document.querySelectorAll('body *');\n    all.forEach(el=>{\n      if(isBookCandidate(el)){\n        el.classList.add('ms-backend-bookbar');\n        // Remove fixed-position geometry that would otherwise keep it floating.\n        el.style.setProperty('position','relative','important');\n        el.style.setProperty('left','auto','important');\n        el.style.setProperty('right','auto','important');\n        el.style.setProperty('bottom','auto','important');\n        el.style.setProperty('top','auto','important');\n        el.style.setProperty('width','100%','important');\n        el.style.setProperty('max-width','100%','important');\n      }\n    });\n  }\n\n  // Backend may inject the button after the page has loaded.\n  fixBookBars();\n  new MutationObserver(fixBookBars).observe(document.body,{childList:true,subtree:true});\n  window.addEventListener('resize',fixBookBars,{passive:true});\n})();\n</script>\n\n\n<script id="ms-v6-language-fit">\n(function(){\n  const svg=document.querySelector('.poster > svg');\n  const select=document.getElementById('ms-language');\n  if(!svg)return;\n\n  /*\n   * Safe widths are in original 1080x1350 SVG coordinates.\n   * They deliberately stop before the feather, icons and ₹21 badge.\n   */\n  const SAFE={\n    0:440, 1:250, 2:450, 3:390, 4:850, 5:520,\n    6:650,\n    7:135,8:135,9:135,10:110,11:110,\n    12:100,13:105,14:85,15:85,\n    16:500,17:500,18:600,19:900,\n    20:590,21:590,22:650,23:650,\n    24:155,25:155,26:155\n  };\n\n  const originals=new Map();\n\n  function remember(){\n    svg.querySelectorAll('text[data-ms-index]').forEach(el=>{\n      const i=Number(el.dataset.msIndex);\n      if(originals.has(i))return;\n      originals.set(i,{\n        font:el.getAttribute('font-size')||'16',\n        transform:el.getAttribute('transform')||'',\n        x:el.getAttribute('x')||'0',\n        y:el.getAttribute('y')||'0',\n        anchor:el.getAttribute('text-anchor')||'start',\n        safe:SAFE[i] || Number(el.dataset.msMaxWidth) || 500\n      });\n    });\n  }\n\n  function reset(el,o){\n    el.setAttribute('font-size',o.font);\n    if(o.transform)el.setAttribute('transform',o.transform);\n    else el.removeAttribute('transform');\n    el.removeAttribute('textLength');\n    el.removeAttribute('lengthAdjust');\n  }\n\n  function measure(el){\n    try{\n      return el.getComputedTextLength();\n    }catch(e){\n      try{return el.getBBox().width}catch(_){return 0}\n    }\n  }\n\n  function fitOne(el,o){\n    reset(el,o);\n\n    const safe=o.safe;\n    let w=measure(el);\n    if(!w || w<=safe)return;\n\n    /*\n     * First reduce font size, but never below 62% of the original artwork\n     * size. This keeps long-language headings readable.\n     */\n    const original=parseFloat(o.font)||16;\n    const reduced=Math.max(original*0.62, original*(safe/w));\n    el.setAttribute('font-size',String(reduced));\n\n    w=measure(el);\n\n    /*\n     * SVG textLength is the final hard boundary. Unlike a CSS width,\n     * this guarantees that the actual glyphs stay inside the design area.\n     */\n    if(w>safe){\n      el.setAttribute('textLength',String(safe));\n      el.setAttribute('lengthAdjust','spacingAndGlyphs');\n    }\n  }\n\n  function fit(){\n    remember();\n    svg.querySelectorAll('text[data-ms-index]').forEach(el=>{\n      const o=originals.get(Number(el.dataset.msIndex));\n      if(o)fitOne(el,o);\n    });\n  }\n\n  function run(){\n    /* Two animation frames let the browser apply the newly selected text\n       before measuring it, without waiting for document.fonts.ready. */\n    requestAnimationFrame(()=>requestAnimationFrame(fit));\n  }\n\n  run();\n\n  if(select){\n    select.addEventListener('change',run);\n  }\n\n  let resizeTimer=0;\n  window.addEventListener('resize',()=>{\n    clearTimeout(resizeTimer);\n    resizeTimer=setTimeout(run,80);\n  },{passive:true});\n})();\n</script>\n\n\n<script id="ms-v8-book-after-poster">\n(function(){\n  function normalize(){\n    document.querySelectorAll('button.book-now-trigger,a.styled-btn').forEach(function(el){\n      el.style.setProperty('position','static','important');\n      el.style.setProperty('inset','auto','important');\n      el.style.setProperty('transform','none','important');\n      el.style.setProperty('margin','12px','important');\n      el.style.setProperty('width','calc(100% - 24px)','important');\n\n      /* If the button itself is nested inside a fixed/sticky wrapper,\n         move only that wrapper after the campaign, without scanning the\n         whole page or observing recursively. */\n      let p=el.parentElement;\n      for(let i=0;i<3 && p && p!==document.body;i++){\n        const cs=getComputedStyle(p);\n        if(cs.position==='fixed' || cs.position==='sticky'){\n          const campaign=document.querySelector('.campaign-wrapper');\n          if(campaign && campaign.parentElement===document.body){\n            document.body.appendChild(p);\n          }\n          p.style.setProperty('position','static','important');\n          p.style.setProperty('inset','auto','important');\n          p.style.setProperty('width','100%','important');\n          p.style.setProperty('height','auto','important');\n          p.style.setProperty('min-height','0','important');\n          p.style.setProperty('max-height','none','important');\n          p.style.setProperty('transform','none','important');\n          p.style.setProperty('margin','0','important');\n          p.style.setProperty('padding','0','important');\n          p.style.setProperty('overflow','visible','important');\n          break;\n        }\n        p=p.parentElement;\n      }\n    });\n  }\n\n  if(document.readyState==='loading'){\n    document.addEventListener('DOMContentLoaded',normalize,{once:true});\n  }else{\n    normalize();\n  }\n})();\n</script>\n\n</body>\n</html>\n	t	2026-08-25 08:45:17.916	2026-08-25 08:47:28.508
